        # If already has proper nested "function" key, pass through
        if "function" in t:
            converted.append(t)
        elif t.get("type") == "function":
            converted.append({
                "type": "function",
                "function": {
                    "name": t.get("name", ""),
                    "description": t.get("description", ""),
                    "parameters": t.get("parameters", {"type": "object", "properties": {}}),
                }
            })
        else:
            converted.append(t)
    return converted


